selector_to_html = {"a[href=\"#api-map\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">API map<a class=\"headerlink\" href=\"#api-map\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#operators-and-extension-points\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operators and extension points<a class=\"headerlink\" href=\"#operators-and-extension-points\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#stability-boundaries\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Stability boundaries<a class=\"headerlink\" href=\"#stability-boundaries\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#api-reference\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API Reference<a class=\"headerlink\" href=\"#api-reference\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum exposes one curated Python interface: <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code>.</p>", "a[href=\"#errors\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Errors<a class=\"headerlink\" href=\"#errors\" title=\"Link to this heading\">#</a></h2><p>Stable lifecycle categories live in <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.errors</span></code>: <code class=\"docutils literal notranslate\"><span class=\"pre\">ValidationError</span></code> for invalid semantic input, <code class=\"docutils literal notranslate\"><span class=\"pre\">PlanningError</span></code> for a stale, tampered, or incompatible plan, <code class=\"docutils literal notranslate\"><span class=\"pre\">CapabilityError</span></code> for an unavailable requested capability, and <code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionError</span></code> for an execution or training failure. All of them inherit <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagQuantumError</span></code> and their compatible Python built-in exception, so both the narrow and the general <code class=\"docutils literal notranslate\"><span class=\"pre\">except</span></code> clause work.</p>", "a[href=\"#runtime-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Runtime configuration<a class=\"headerlink\" href=\"#runtime-configuration\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">RuntimeConfig</span></code> records backend, device, real and complex precision, JAX precision, matrix-multiplication policy, and drawing style. A circuit captures a configuration when it is constructed and embeds a versioned manifest in its IR and plans, so distributed workers rebuild the same policy instead of inheriting mutable process state. <code class=\"docutils literal notranslate\"><span class=\"pre\">runtime_config(...)</span></code> provides context-local temporary overrides.</p>", "a[href=\"#measurements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Measurements<a class=\"headerlink\" href=\"#measurements\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.expectation</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.probabilities</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.samples</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.counts</span></code> describe what to measure. Pauli products use <code class=\"docutils literal notranslate\"><span class=\"pre\">@</span></code>, Hamiltonian sums and real coefficients use ordinary arithmetic, and sampling or counts accept computational-basis wires or one unweighted Pauli product. Results expose <code class=\"docutils literal notranslate\"><span class=\"pre\">expectation()</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">expectations</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">probabilities</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">samples</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">counts</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">measurement(index_or_name)</span></code>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
